=== FILE: tb/tb_irq_ctrl.sv ===
// Self-checking testbench for irq_ctrl (task prj-486b52a6aa:testbench).
// Requirement: Verify the existing interrupt controller RTL with a SystemVerilog testbench.
// Expected values come from interface_spec.md, through a reference model written
// per source bit from the specification statements and through literal values
// in each directed scenario. No expected value is read back from the DUT.
//
// Scenario -> specification statement
//   S1  reset, write during reset ignored          IRQ-RESET
//   S2  register read/write, upper bits zero        IRQ-REG-RW, IRQ-PARAM
//   S3  detection while disabled                    IRQ-DETECT-DISABLED, IRQ-LEVEL
//   S4  enable raises irq, CLAIM read, no side eff. IRQ-MASK, IRQ-CLAIM, IRQ-READ
//   S5  write-1-to-clear                            IRQ-W1C
//   S6  all pending, ascending claim/ack order      IRQ-PRIORITY, IRQ-ACK
//   S7  masking and reverse-order acknowledge       IRQ-PRIORITY, IRQ-MASK
//   S8  ack out of range, upper wdata bits          IRQ-ACK
//   S9  level source cleared while high             IRQ-SET-WINS
//   S10 rising-edge mode                            IRQ-EDGE, IRQ-SET-WINS
//   S11 two sources at one edge, mixed modes        IRQ-EDGE, IRQ-LEVEL, IRQ-W1C
//   S12 mode change while source held high          IRQ-EDGE
//   S13 reset in mid-operation                      IRQ-RESET
//   S14 seeded random traffic vs reference model    all
// After every clock edge: irq, irq_id and rdata at all four addresses are
// compared against the model (IRQ-LATENCY, IRQ-READ).
`timescale 1ns / 1ps

module irq_ctrl_test #(
    parameter integer N    = 8,
    parameter [31:0]  SEED = 32'h0000_0001
) (
    input  wire        clk,
    output reg         done,
    output reg  [31:0] n_pass,
    output reg  [31:0] n_fail
);
    localparam [31:0] MASK = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);

    reg          rst_n;
    reg  [N-1:0] src;
    reg          we;
    reg  [1:0]   addr;
    reg  [31:0]  wdata;
    wire [31:0]  rdata;
    wire         irq;
    wire [4:0]   irq_id;

    irq_ctrl #(.N(N)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .src   (src),
        .we    (we),
        .addr  (addr),
        .wdata (wdata),
        .rdata (rdata),
        .irq   (irq),
        .irq_id(irq_id)
    );

    // ---------------- reference model (from interface_spec.md) ----------------
    reg [N-1:0] m_enable;
    reg [N-1:0] m_mode;
    reg [N-1:0] m_pending;
    reg [N-1:0] m_src_q;

    function automatic [N-1:0] oh(input integer i);
        begin
            oh    = {N{1'b0}};
            oh[i] = 1'b1;
        end
    endfunction

    function automatic [31:0] oh32(input integer i);
        begin
            oh32    = 32'd0;
            oh32[i] = 1'b1;
        end
    endfunction

    // IRQ-MASK: high exactly when some source is pending and enabled.
    function automatic prio_irq(input [N-1:0] act);
        integer j;
        begin
            prio_irq = 1'b0;
            for (j = 0; j < N; j = j + 1)
                if (act[j]) prio_irq = 1'b1;
        end
    endfunction

    // IRQ-PRIORITY: lowest-numbered pending and enabled source; 0 when none.
    function automatic [4:0] prio_id(input [N-1:0] act);
        integer j;
        reg     found;
        begin
            prio_id = 5'd0;
            found   = 1'b0;
            for (j = 0; j < N; j = j + 1)
                if (!found && act[j]) begin
                    prio_id = j[4:0];
                    found   = 1'b1;
                end
        end
    endfunction

    // Register map and IRQ-CLAIM.
    function automatic [31:0] exp_rdata(input [1:0] a);
        reg [31:0] r;
        begin
            r = 32'd0;
            case (a)
                2'd0: r[N-1:0] = m_enable;
                2'd1: r[N-1:0] = m_mode;
                2'd2: r[N-1:0] = m_pending;
                default: begin
                    r[31]  = prio_irq(m_pending & m_enable);
                    r[4:0] = prio_id(m_pending & m_enable);
                end
            endcase
            exp_rdata = r;
        end
    endfunction

    // One rising edge with rst_n high.
    task automatic model_step(input [N-1:0] s, input w, input [1:0] a, input [31:0] d);
        integer     j;
        reg         det;
        reg         clr;
        reg [N-1:0] nxt;
        begin
            nxt = m_pending;
            for (j = 0; j < N; j = j + 1) begin
                // IRQ-LEVEL / IRQ-EDGE; ENABLE is not consulted (IRQ-DETECT-DISABLED).
                if (m_mode[j]) det = s[j] && !m_src_q[j];
                else           det = s[j];
                // IRQ-W1C and IRQ-ACK (a number of N or more matches no j).
                clr = (w && a == 2'd2 && d[j]) || (w && a == 2'd3 && d[4:0] == j);
                // IRQ-SET-WINS: detection beats a clear at the same edge.
                if (det)      nxt[j] = 1'b1;
                else if (clr) nxt[j] = 1'b0;
            end
            if (w && a == 2'd0) m_enable = d[N-1:0];
            if (w && a == 2'd1) m_mode   = d[N-1:0];
            m_pending = nxt;
            m_src_q   = s;
        end
    endtask

    task automatic model_reset;
        begin
            m_enable  = {N{1'b0}};
            m_mode    = {N{1'b0}};
            m_pending = {N{1'b0}};
            m_src_q   = {N{1'b0}};
        end
    endtask

    // ---------------- checking ----------------
    task automatic check_eq(input [31:0] got, input [31:0] want, input string what, input string field);
        begin
            if (got === want) begin
                n_pass = n_pass + 1;
            end else begin
                n_fail = n_fail + 1;
                $display("FAIL [N=%0d] t=%0t %s / %s (addr=%0d): got 0x%08h, expected 0x%08h",
                         N, $time, what, field, addr, got, want);
            end
        end
    endtask

    // Called 1 ns after a rising edge; takes 4 ns.
    task automatic check_all(input string what);
        integer k;
        begin
            we = 1'b0;
            check_eq({31'd0, irq},    {31'd0, prio_irq(m_pending & m_enable)}, what, "irq vs model");
            check_eq({27'd0, irq_id}, {27'd0, prio_id(m_pending & m_enable)},  what, "irq_id vs model");
            for (k = 0; k < 4; k = k + 1) begin
                addr = k[1:0];
                #1;
                check_eq(rdata, exp_rdata(k[1:0]), what, "rdata vs model");
            end
        end
    endtask

    // Literal read check, no write; takes 1 ns.
    task automatic peek(input [1:0] a, input [31:0] want, input string what);
        begin
            we   = 1'b0;
            addr = a;
            #1;
            check_eq(rdata, want, what, "rdata literal");
        end
    endtask

    task automatic expect_irq(input e_irq, input integer e_id, input string what);
        begin
            check_eq({31'd0, irq}, {31'd0, e_irq}, what, "irq literal");
            check_eq({27'd0, irq_id}, e_id,        what, "irq_id literal");
        end
    endtask

    // Drive inputs away from the edge, take one rising edge, then check.
    task automatic cycle(input [N-1:0] s, input w, input [1:0] a, input [31:0] d, input string what);
        begin
            src   = s;
            we    = w;
            addr  = a;
            wdata = d;
            @(posedge clk);
            model_step(s, w, a, d);
            #1;
            check_all(what);
        end
    endtask

    task automatic do_reset(input [N-1:0] s, input w, input [1:0] a, input [31:0] d,
                            input integer cycles, input string what);
        begin
            rst_n = 1'b0;
            src   = s;
            we    = w;
            addr  = a;
            wdata = d;
            repeat (cycles) @(posedge clk);
            model_reset;
            #1;
            rst_n = 1'b1;
            check_all(what);
        end
    endtask

    function automatic [31:0] xs32(input [31:0] x);
        reg [31:0] y;
        begin
            y    = x ^ (x << 13);
            y    = y ^ (y >> 17);
            y    = y ^ (y << 5);
            xs32 = y;
        end
    endfunction

    // ---------------- scenarios ----------------
    integer     i;
    integer     it;
    integer     ahi;
    integer     amid;
    reg [31:0]  lfsr, r1, r2, r3, r4, d_r;
    reg         w_r;
    reg [1:0]   a_r;

    initial begin
        done      = 1'b0;
        n_pass    = 32'd0;
        n_fail    = 32'd0;
        rst_n     = 1'b0;
        src       = {N{1'b0}};
        we        = 1'b0;
        addr      = 2'd0;
        wdata     = 32'd0;
        model_reset;
        ahi       = N - 1;
        amid      = N / 2;

        // S1: reset; a write held during reset must not land.
        do_reset({N{1'b0}}, 1'b1, 2'd0, 32'hFFFF_FFFF, 2, "S1 reset with write held");
        peek(2'd0, 32'd0, "S1 ENABLE zero after reset");
        peek(2'd1, 32'd0, "S1 MODE zero after reset");
        peek(2'd2, 32'd0, "S1 PENDING zero after reset");
        expect_irq(1'b0, 0, "S1 no irq after reset");

        // S2: register read/write; bits N and up read zero.
        cycle({N{1'b0}}, 1'b1, 2'd0, 32'hFFFF_FFFF, "S2 write ENABLE all ones");
        peek(2'd0, MASK, "S2 ENABLE holds N bits only");
        peek(2'd1, 32'd0, "S2 MODE unchanged by ENABLE write");
        cycle({N{1'b0}}, 1'b1, 2'd1, 32'hA5A5_A5A5, "S2 write MODE");
        peek(2'd1, 32'hA5A5_A5A5 & MASK, "S2 MODE readback");
        peek(2'd0, MASK, "S2 ENABLE unchanged by MODE write");
        cycle({N{1'b0}}, 1'b1, 2'd0, 32'h5A5A_5A5A, "S2 write ENABLE pattern");
        peek(2'd0, 32'h5A5A_5A5A & MASK, "S2 ENABLE pattern readback");
        cycle({N{1'b0}}, 1'b1, 2'd1, 32'd0, "S2 clear MODE");
        cycle({N{1'b0}}, 1'b1, 2'd0, 32'd0, "S2 clear ENABLE");
        peek(2'd0, 32'd0, "S2 ENABLE cleared");
        peek(2'd1, 32'd0, "S2 MODE cleared");
        cycle({N{1'b0}}, 1'b1, 2'd2, 32'hFFFF_FFFF, "S2 W1C on empty PENDING");
        peek(2'd2, 32'd0, "S2 W1C never sets");
        cycle({N{1'b0}}, 1'b1, 2'd3, 32'd0, "S2 ack with nothing pending");
        peek(2'd2, 32'd0, "S2 ack never sets");

        // S3: a disabled level source still sets PENDING; no irq.
        cycle(oh(1), 1'b0, 2'd0, 32'd0, "S3 level pulse on disabled source 1");
        peek(2'd2, oh32(1), "S3 PENDING set while disabled");
        expect_irq(1'b0, 0, "S3 disabled source raises no irq");
        cycle({N{1'b0}}, 1'b0, 2'd0, 32'd0, "S3 source low, pending holds");
        peek(2'd2, oh32(1), "S3 PENDING sticky");

        // S4: enabling raises irq; reading CLAIM does not acknowledge.
        cycle({N{1'b0}}, 1'b1, 2'd0, oh32(1), "S4 enable source 1");
        expect_irq(1'b1, 1, "S4 irq for source 1");
        peek(2'd3, 32'h8000_0001, "S4 CLAIM read");
        cycle({N{1'b0}}, 1'b0, 2'd3, 32'd1, "S4 CLAIM selected, no write");
        peek(2'd2, oh32(1), "S4 CLAIM read leaves PENDING");
        expect_irq(1'b1, 1, "S4 irq still high");

        // S5: write-1-to-clear.
        cycle({N{1'b0}}, 1'b1, 2'd2, 32'd0, "S5 PENDING write of zeros");
        peek(2'd2, oh32(1), "S5 zeros leave PENDING");
        cycle({N{1'b0}}, 1'b1, 2'd2, ~oh32(1), "S5 W1C of other bits");
        peek(2'd2, oh32(1), "S5 other bits leave source 1");
        cycle({N{1'b0}}, 1'b1, 2'd2, oh32(1), "S5 W1C source 1");
        peek(2'd2, 32'd0, "S5 source 1 cleared");
        expect_irq(1'b0, 0, "S5 irq low after clear");

        // S6: every source pending; claims come out lowest first.
        cycle({N{1'b0}}, 1'b1, 2'd0, 32'hFFFF_FFFF, "S6 enable all");
        cycle({N{1'b1}}, 1'b0, 2'd0, 32'd0, "S6 pulse every source");
        cycle({N{1'b0}}, 1'b0, 2'd0, 32'd0, "S6 sources low");
        peek(2'd2, MASK, "S6 all pending");
        for (i = 0; i < N; i = i + 1) begin
            expect_irq(1'b1, i, "S6 claim names lowest pending");
            peek(2'd3, 32'h8000_0000 | i, "S6 CLAIM read");
            cycle({N{1'b0}}, 1'b1, 2'd3, i, "S6 acknowledge claimed source");
        end
        expect_irq(1'b0, 0, "S6 all acknowledged");
        peek(2'd2, 32'd0, "S6 PENDING empty");
        peek(2'd3, 32'd0, "S6 CLAIM reads zero when idle");

        // S7: ENABLE masks the claim; acknowledging from the top keeps id 0.
        cycle({N{1'b1}}, 1'b0, 2'd0, 32'd0, "S7 pulse every source");
        cycle({N{1'b0}}, 1'b1, 2'd0, oh32(ahi), "S7 enable only highest");
        expect_irq(1'b1, ahi, "S7 highest-numbered enabled source claimed");
        cycle({N{1'b0}}, 1'b1, 2'd0, oh32(ahi) | oh32(amid), "S7 enable mid and highest");
        expect_irq(1'b1, amid, "S7 lower of two enabled wins");
        cycle({N{1'b0}}, 1'b1, 2'd0, 32'd0, "S7 disable all");
        expect_irq(1'b0, 0, "S7 no irq when all disabled");
        peek(2'd2, MASK, "S7 PENDING kept while disabled");
        cycle({N{1'b0}}, 1'b1, 2'd0, 32'hFFFF_FFFF, "S7 enable all");
        for (i = N - 1; i >= 1; i = i - 1) begin
            cycle({N{1'b0}}, 1'b1, 2'd3, i, "S7 acknowledge from the top");
            expect_irq(1'b1, 0, "S7 source 0 still claimed");
        end
        cycle({N{1'b0}}, 1'b1, 2'd3, 32'd0, "S7 acknowledge source 0");
        expect_irq(1'b0, 0, "S7 all acknowledged");

        // S8: acknowledge range and upper wdata bits.
        cycle(oh(0) | oh(ahi), 1'b0, 2'd0, 32'd0, "S8 pulse sources 0 and top");
        cycle({N{1'b0}}, 1'b0, 2'd0, 32'd0, "S8 sources low");
        if (N < 32) begin
            cycle({N{1'b0}}, 1'b1, 2'd3, N, "S8 ack number N ignored");
            peek(2'd2, oh32(0) | oh32(ahi), "S8 ack N changes nothing");
            cycle({N{1'b0}}, 1'b1, 2'd3, 32'd31, "S8 ack number 31 ignored");
            peek(2'd2, oh32(0) | oh32(ahi), "S8 ack 31 changes nothing");
            expect_irq(1'b1, 0, "S8 claim unchanged");
        end
        cycle({N{1'b0}}, 1'b1, 2'd3, 32'hFFFF_FFE0, "S8 ack 0 with upper wdata bits set");
        peek(2'd2, oh32(ahi), "S8 only source 0 acknowledged");
        expect_irq(1'b1, ahi, "S8 top source now claimed");
        cycle({N{1'b0}}, 1'b1, 2'd3, ahi, "S8 ack top source");
        peek(2'd2, 32'd0, "S8 PENDING empty");

        // S9: a level source cleared while its input is high stays pending.
        cycle(oh(1), 1'b0, 2'd0, 32'd0, "S9 level source 1 high");
        expect_irq(1'b1, 1, "S9 irq for source 1");
        cycle(oh(1), 1'b1, 2'd3, 32'd1, "S9 ack while input high");
        peek(2'd2, oh32(1), "S9 set wins over ack");
        expect_irq(1'b1, 1, "S9 irq stays high");
        cycle(oh(1), 1'b1, 2'd2, oh32(1), "S9 W1C while input high");
        peek(2'd2, oh32(1), "S9 set wins over W1C");
        cycle({N{1'b0}}, 1'b1, 2'd2, oh32(1), "S9 W1C after input low");
        peek(2'd2, 32'd0, "S9 cleared once low");

        // S10: rising-edge mode.
        cycle({N{1'b0}}, 1'b1, 2'd1, 32'hFFFF_FFFF, "S10 all sources rising edge");
        peek(2'd1, MASK, "S10 MODE all edge");
        cycle(oh(ahi), 1'b0, 2'd0, 32'd0, "S10 rising edge on top source");
        peek(2'd2, oh32(ahi), "S10 edge sets PENDING");
        expect_irq(1'b1, ahi, "S10 irq for edge source");
        cycle(oh(ahi), 1'b1, 2'd3, ahi, "S10 ack while input held high");
        peek(2'd2, 32'd0, "S10 held edge source clears");
        expect_irq(1'b0, 0, "S10 irq low");
        cycle(oh(ahi), 1'b0, 2'd0, 32'd0, "S10 input still high");
        peek(2'd2, 32'd0, "S10 held high sets only once");
        cycle(oh(ahi), 1'b0, 2'd0, 32'd0, "S10 input still high again");
        peek(2'd2, 32'd0, "S10 still not pending");
        cycle({N{1'b0}}, 1'b0, 2'd0, 32'd0, "S10 input falls");
        peek(2'd2, 32'd0, "S10 falling edge sets nothing");
        cycle(oh(ahi), 1'b1, 2'd3, ahi, "S10 new rise with same-edge ack");
        peek(2'd2, oh32(ahi), "S10 edge detection wins over ack");
        cycle(oh(ahi), 1'b1, 2'd2, MASK, "S10 W1C while held");
        peek(2'd2, 32'd0, "S10 cleared, no new edge");
        cycle({N{1'b0}}, 1'b0, 2'd0, 32'd0, "S10 input low");

        // S11: two sources at one edge, source 0 edge, others level.
        cycle({N{1'b0}}, 1'b1, 2'd1, oh32(0), "S11 source 0 edge, rest level");
        cycle(oh(0) | oh(1), 1'b0, 2'd0, 32'd0, "S11 sources 0 and 1 rise together");
        peek(2'd2, oh32(0) | oh32(1), "S11 both pending");
        expect_irq(1'b1, 0, "S11 source 0 claimed");
        cycle(oh(0) | oh(1), 1'b1, 2'd2, oh32(0) | oh32(1), "S11 W1C both while held");
        peek(2'd2, oh32(1), "S11 edge clears, level stays");
        expect_irq(1'b1, 1, "S11 source 1 claimed");
        cycle({N{1'b0}}, 1'b1, 2'd2, MASK, "S11 clear all after low");
        peek(2'd2, 32'd0, "S11 PENDING empty");

        // S12: switch a held-high source from level to edge.
        cycle({N{1'b0}}, 1'b1, 2'd1, 32'd0, "S12 all level");
        cycle(oh(1), 1'b0, 2'd0, 32'd0, "S12 level source 1 high");
        cycle(oh(1), 1'b1, 2'd1, oh32(1), "S12 switch source 1 to edge while high");
        peek(2'd2, oh32(1), "S12 still pending");
        cycle(oh(1), 1'b1, 2'd2, oh32(1), "S12 clear in edge mode, input still high");
        peek(2'd2, 32'd0, "S12 no new edge after switch");
        cycle(oh(1), 1'b0, 2'd0, 32'd0, "S12 input held");
        peek(2'd2, 32'd0, "S12 still not pending");
        cycle({N{1'b0}}, 1'b0, 2'd0, 32'd0, "S12 input low");

        // S13: reset in mid-operation.
        cycle(oh(1), 1'b0, 2'd0, 32'd0, "S13 rising edge on source 1");
        expect_irq(1'b1, 1, "S13 irq before reset");
        do_reset(oh(1), 1'b0, 2'd0, 32'd0, 1, "S13 reset in mid-operation");
        peek(2'd0, 32'd0, "S13 ENABLE cleared");
        peek(2'd1, 32'd0, "S13 MODE cleared");
        peek(2'd2, 32'd0, "S13 PENDING cleared");
        expect_irq(1'b0, 0, "S13 irq low after reset");
        cycle(oh(1), 1'b0, 2'd0, 32'd0, "S13 level detection after reset");
        peek(2'd2, oh32(1), "S13 source 1 pending in level mode");
        expect_irq(1'b0, 0, "S13 disabled after reset");

        // S14: seeded random traffic against the reference model.
        lfsr = (SEED == 32'd0) ? 32'h1 : SEED;
        for (it = 0; it < 400; it = it + 1) begin
            lfsr = xs32(lfsr); r1 = lfsr;
            lfsr = xs32(lfsr); r2 = lfsr;
            lfsr = xs32(lfsr); r3 = lfsr;
            lfsr = xs32(lfsr); r4 = lfsr;
            if (r3[15:8] == 8'd0) begin
                do_reset(r1[N-1:0] & r2[N-1:0], 1'b0, 2'd0, 32'd0, 1, "S14 random reset");
            end else begin
                w_r = (r3[1:0] == 2'b00);
                a_r = r3[3:2];
                d_r = (a_r == 2'd3 && !r3[5]) ? {27'd0, prio_id(m_pending & m_enable)} : r4;
                cycle(r1[N-1:0] & r2[N-1:0], w_r, a_r, d_r, "S14 random");
            end
        end

        $display("irq_ctrl_test N=%0d: %0d passed, %0d failed", N, n_pass, n_fail);
        done = 1'b1;
    end
endmodule

module tb_irq_ctrl;
    reg clk = 1'b0;
    always #5 clk = ~clk;

    wire        d2, d5, d8, d32;
    wire [31:0] p2, p5, p8, p32;
    wire [31:0] f2, f5, f8, f32;

    irq_ctrl_test #(.N(2),  .SEED(32'h0000_2A71)) t_n2  (.clk(clk), .done(d2),  .n_pass(p2),  .n_fail(f2));
    irq_ctrl_test #(.N(5),  .SEED(32'h1357_9BDF)) t_n5  (.clk(clk), .done(d5),  .n_pass(p5),  .n_fail(f5));
    irq_ctrl_test #(.N(8),  .SEED(32'hC0FF_EE11)) t_n8  (.clk(clk), .done(d8),  .n_pass(p8),  .n_fail(f8));
    irq_ctrl_test #(.N(32), .SEED(32'h8BAD_F00D)) t_n32 (.clk(clk), .done(d32), .n_pass(p32), .n_fail(f32));

    string     nonce;
    reg        have_nonce;
    reg        verdict_printed;
    reg [31:0] tp;
    reg [31:0] tf;

    initial begin
        verdict_printed = 1'b0;
        have_nonce      = 1'b0;
        nonce           = "";
        if      ($value$plusargs("nonce=%s", nonce))             have_nonce = 1'b1;
        else if ($value$plusargs("NONCE=%s", nonce))             have_nonce = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce))     have_nonce = 1'b1;
        else if ($value$plusargs("NIRMAAN_NONCE=%s", nonce))     have_nonce = 1'b1;
        else if ($value$plusargs("nirmaan_sim_nonce=%s", nonce)) have_nonce = 1'b1;
        else if ($value$plusargs("NIRMAAN_SIM_NONCE=%s", nonce)) have_nonce = 1'b1;
        else if ($value$plusargs("sim_nonce=%s", nonce))         have_nonce = 1'b1;
        else if ($value$plusargs("SIM_NONCE=%s", nonce))         have_nonce = 1'b1;
        else if ($value$plusargs("nirmaan=%s", nonce))           have_nonce = 1'b1;
        else if ($value$plusargs("NIRMAAN=%s", nonce))           have_nonce = 1'b1;
        if (!have_nonce)
            $display("tb_irq_ctrl: WARNING no nonce plusarg found");

        while ((d2 & d5 & d8 & d32) !== 1'b1) @(posedge clk);
        #1;
        tp = p2 + p5 + p8 + p32;
        tf = f2 + f5 + f8 + f32;
        if (!verdict_printed) begin
            verdict_printed = 1'b1;
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, tp, tf);
        end
        $finish;
    end

    // Watchdog: a hang is reported as a failure.
    initial begin
        #1000000;
        if (!verdict_printed) begin
            verdict_printed = 1'b1;
            $display("tb_irq_ctrl: watchdog expired before all instances finished");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce,
                     p2 + p5 + p8 + p32, f2 + f5 + f8 + f32 + 32'd1);
            $finish;
        end
    end
endmodule
